import{_ as t,o as a,c as i,ag as l}from"./chunks/framework.B5ULsuav.js";const c=JSON.parse('{"title":"儒学者 / 普通人入口","description":"","frontmatter":{},"headers":[],"relativePath":"30-学习路径/path-儒学者.md","filePath":"30-学习路径/path-儒学者.md","lastUpdated":1778155802000}'),r={name:"30-学习路径/path-儒学者.md"};function e(h,o,d,u,s,n){return a(),i("div",null,[...o[0]||(o[0]=[l('<h1 id="儒学者-普通人入口" tabindex="-1">儒学者 / 普通人入口 <a class="header-anchor" href="#儒学者-普通人入口" aria-label="Permalink to &quot;儒学者 / 普通人入口&quot;">​</a></h1><blockquote><p>如果你不修行、不念佛、不练功——只想过好这一生，把家庭照顾好，把工作做好。 了空居士的体系恰恰<strong>从你每天的生活开始</strong>。</p></blockquote><hr><h2 id="你不是-修行人-但你已经在修行" tabindex="-1">你不是&quot;修行人&quot;，但你已经在修行 <a class="header-anchor" href="#你不是-修行人-但你已经在修行" aria-label="Permalink to &quot;你不是&quot;修行人&quot;，但你已经在修行&quot;">​</a></h2><p>了空居士说：<strong>&quot;家庭是道场，工作单位是道场，社会是道场。&quot;</strong> 不是让你去庙里打坐，是让你在日常中把日子过好：</p><ul><li>对家人好 → 这就是历境炼心</li><li>认真工作 → 这就是禅定</li><li>与人为善 → 这就是心能安静的基础</li></ul><p><strong>不需要任何宗教背景或修行基础。</strong> 你只需要愿意把自己的生活过得更好。</p><hr><h2 id="推荐学习路径" tabindex="-1">推荐学习路径 <a class="header-anchor" href="#推荐学习路径" aria-label="Permalink to &quot;推荐学习路径&quot;">​</a></h2><h3 id="第一步-三句话改变一天" tabindex="-1">第一步：三句话改变一天 <a class="header-anchor" href="#第一步-三句话改变一天" aria-label="Permalink to &quot;第一步：三句话改变一天&quot;">​</a></h3><blockquote><p><strong>&quot;保持平静的要诀就是保持理智地去看待一切。不平静的时候问自己：&#39;我为什么要不平静？这样正确吗？&#39;&quot;</strong> — <a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></p></blockquote><blockquote><p><strong>&quot;凡事尽力而为，做人问心无愧。&quot;</strong> — 答疑精选</p></blockquote><blockquote><p><strong>&quot;因上精进，果上随缘——过程努力，结果不执着。&quot;</strong> — <a href="/liaokongjushi-wisdom/60-原文段落/道德经14章-因上精进果上随缘">道德经14章-因上精进果上随缘</a></p></blockquote><p>今天遇到任何不顺心的事，就用这三句话。不需要任何&quot;修行&quot;动作。</p><h3 id="第二步-了解三个处世模型" tabindex="-1">第二步：了解三个处世模型 <a class="header-anchor" href="#第二步-了解三个处世模型" aria-label="Permalink to &quot;第二步：了解三个处世模型&quot;">​</a></h3><ol><li><p><strong>圆融中和</strong> — 不走极端</p><ul><li>&quot;凡夫开口闭口都是边见&quot;——试试不站队，看看第三种可能</li><li>读：<a href="/liaokongjushi-wisdom/10-核心模型/model-圆融中和">圆融中和模型</a></li></ul></li><li><p><strong>自然务实</strong> — 抓核心，做实事</p><ul><li>&quot;做就是了&quot;——不要想太多，先做一小步</li><li>读：<a href="/liaokongjushi-wisdom/10-核心模型/model-自然务实">自然务实模型</a></li></ul></li><li><p><strong>历境炼心</strong> — 把每一件事当作成长</p><ul><li>被人批评了？&quot;烦恼即菩提&quot;——看看能学到什么</li><li>读：<a href="/liaokongjushi-wisdom/10-核心模型/model-历境炼心">历境炼心模型</a></li></ul></li></ol><h3 id="第三步-面对具体问题" tabindex="-1">第三步：面对具体问题 <a class="header-anchor" href="#第三步-面对具体问题" aria-label="Permalink to &quot;第三步：面对具体问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你的问题</th><th>直接去看</th></tr></thead><tbody><tr><td>经常和家人吵架</td><td><a href="/liaokongjushi-wisdom/50-概念资料/dict-家庭道场">家庭道场</a> + <a href="/liaokongjushi-wisdom/20-专题研究/topic-人际关系">如何处理人际关系</a></td></tr><tr><td>不知道怎么教育小孩</td><td><a href="/liaokongjushi-wisdom/20-专题研究/topic-亲子教育">如何教育子女</a></td></tr><tr><td>工作压力大、焦虑</td><td><a href="/liaokongjushi-wisdom/20-专题研究/topic-焦虑">如何面对焦虑</a> + <a href="/liaokongjushi-wisdom/20-专题研究/topic-工作修行">在工作中修行</a></td></tr><tr><td>被人伤害了放不下</td><td><a href="/liaokongjushi-wisdom/20-专题研究/topic-忍辱与原谅">如何面对忍辱与原谅</a></td></tr><tr><td>为钱烦恼</td><td><a href="/liaokongjushi-wisdom/20-专题研究/topic-财富与布施">如何看待财富与布施</a></td></tr></tbody></table><hr><h2 id="你可能问的问题" tabindex="-1">你可能问的问题 <a class="header-anchor" href="#你可能问的问题" aria-label="Permalink to &quot;你可能问的问题&quot;">​</a></h2><h3 id="q-我不信佛、不信道-这些道理能用吗" tabindex="-1">Q：我不信佛、不信道，这些道理能用吗？ <a class="header-anchor" href="#q-我不信佛、不信道-这些道理能用吗" aria-label="Permalink to &quot;Q：我不信佛、不信道，这些道理能用吗？&quot;">​</a></h3><p><strong>A</strong>：能用。了空居士说的&quot;保持理智&quot;&quot;抓核心&quot;&quot;不极端&quot;&quot;将心比心&quot;——这些都是普世智慧，不需要信仰前提。他就是用现代话把古人智慧翻译了一遍。</p><h3 id="q-我生活很忙-没时间搞这些" tabindex="-1">Q：我生活很忙，没时间搞这些 <a class="header-anchor" href="#q-我生活很忙-没时间搞这些" aria-label="Permalink to &quot;Q：我生活很忙，没时间搞这些&quot;">​</a></h3><p><strong>A</strong>：不需要专门时间。&quot;与人为善&quot;&quot;观察念头&quot;&quot;遇事先停三秒&quot;——这些恰恰是你每天在做的，只是以前没意识。现在有意识地做就行了。</p><h3 id="q-这些道理太简单了-有用吗" tabindex="-1">Q：这些道理太简单了，有用吗？ <a class="header-anchor" href="#q-这些道理太简单了-有用吗" aria-label="Permalink to &quot;Q：这些道理太简单了，有用吗？&quot;">​</a></h3><p><strong>A</strong>：了空居士说&quot;学东西不要追求&#39;学完&#39;，追求&#39;用上一条就赚一条&#39;。&quot; 你不需要全搞懂，今天就用一条——比如&quot;不平静时问自己我为什么不平静&quot;——就够了。</p><hr><h2 id="儒家处世概念" tabindex="-1">儒家处世概念 <a class="header-anchor" href="#儒家处世概念" aria-label="Permalink to &quot;儒家处世概念&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-处世">dict-处世</a> — 在人际关系中修行</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-正">dict-正</a> — 什么是&quot;对&quot;的事（整体观定善恶）</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-恕">dict-恕</a> — 己所不欲勿施于人</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-敬">dict-敬</a> — 尊重每一个人</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-家庭道场">dict-家庭道场</a> — 家庭是最好的修行场所</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-义">dict-义</a> — 该做就做，义利统一</li></ul><h2 id="儒家金句" tabindex="-1">儒家金句 <a class="header-anchor" href="#儒家金句" aria-label="Permalink to &quot;儒家金句&quot;">​</a></h2><p><a href="/liaokongjushi-wisdom/40-原话金句/quote-儒家">儒家金句全集</a> — 家庭、处世、人生智慧</p><hr><blockquote><p>创建日期：2026-05-07</p></blockquote>',33)])])}const p=t(r,[["render",e]]);export{c as __pageData,p as default};
